CREATE TABLE dbo.t2 (id INT NOT NULL, name VARCHAR(20) NULL, amount DECIMAL(10, 2));
INSERT INTO dbo.t2 (id, name, amount) VALUES (1, 'a', 1.5), (2, NULL, 2.25);
SELECT id, name, amount FROM dbo.t2 ORDER BY id

CREATE TABLE dbo.t2 (a INT, b INT);
INSERT INTO dbo.t2 (a, b) VALUES (1, 2), (2, 3);
CREATE VIEW dbo.v AS SELECT a, b FROM dbo.t2 WHERE a > 1;
SELECT a, b FROM dbo.v

CREATE TABLE dbo.t2 (a INT, b INT);
INSERT INTO dbo.t2 (a, b) VALUES (1, 2), (2, 3);
INSERT INTO dbo.t2 (a, b) SELECT a + 10, b FROM dbo.t2;
SELECT COUNT(*) AS c, MAX(a) AS m FROM dbo.t2

CREATE TABLE dbo.t2 (a INT, b INT, s VARCHAR(5));
INSERT INTO dbo.t2 (a, b, s) VALUES (1, 2, 'x'), (2, 3, 'y');
UPDATE dbo.t2 SET b = b * 10, s = NULL WHERE a = 2;
SELECT a, b, s FROM dbo.t2 ORDER BY a

CREATE TABLE dbo.t2 (a INT, b INT);
INSERT INTO dbo.t2 (a, b) VALUES (1, 2), (2, 3);
UPDATE t SET b = u.b FROM dbo.t2 AS t INNER JOIN (VALUES (1, 100)) AS u(a, b) ON t.a = u.a;
SELECT a, b FROM dbo.t2 ORDER BY a

CREATE TABLE dbo.t2 (a INT, s VARCHAR(5));
INSERT INTO dbo.t2 (a, s) VALUES (1, 'x'), (2, NULL);
DELETE FROM dbo.t2 WHERE s = 'x';
DELETE FROM dbo.t2 WHERE s = NULL;
SELECT a FROM dbo.t2

CREATE TABLE dbo.t2 (a INT);
INSERT INTO dbo.t2 (a) VALUES (1), (2);
TRUNCATE TABLE dbo.t2;
SELECT COUNT(*) AS c FROM dbo.t2

CREATE TABLE dbo.t2 (a INT, b INT, s VARCHAR(5));
INSERT INTO dbo.t2 (a, b, s) VALUES (1, 2, 'x'), (2, 3, 'y');
MERGE dbo.t2 AS d USING (SELECT 2 AS a, 30 AS b UNION ALL SELECT 5, 50) AS s ON d.a = s.a WHEN MATCHED THEN UPDATE SET b = s.b WHEN NOT MATCHED THEN INSERT (a, b, s) VALUES (s.a, s.b, 'n');
SELECT a, b, s FROM dbo.t2 ORDER BY a

CREATE TABLE dbo.t2 (a INT, b INT);
INSERT INTO dbo.t2 (a, b) VALUES (1, 2), (2, 3);
MERGE dbo.t2 AS d USING (SELECT 1 AS a) AS s ON d.a = s.a WHEN MATCHED THEN DELETE WHEN NOT MATCHED BY SOURCE THEN UPDATE SET b = 0;
SELECT a, b FROM dbo.t2 ORDER BY a

